var n=`0659-pepper-soup`;var t=`world-0659`;var a=`NG`;var r=`western-africa`;var s=4;var o=66;var g={en:`Pepper Soup`,ua:`Перцевий суп`};var l={en:`Pepper Soup is a Nigeria classic prepared with goat meat, yellow onion, ginger root, garlic. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Перцевий суп, страва кухні країни Нігерія зі складниками: козлятина, жовта цибуля, корінь імбиру, часник. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var m=[{en:`Combine these ingredients in a pot, bring just to a boil and skim any foam. Simmer gently for about 30 minutes to make a flavorful base.`,ua:`З’єднайте складники в каструлі, доведіть майже до кипіння та зніміть піну. Варіть на малому вогні приблизно 30 хвилин для насиченої основи.`,t:[`simmering`,`skimming-foam`],m:30,i:[[`goat-meat`,720,`g`],[`water`,1250,`ml`],[`yellow-onion`,150,`g`],[`ginger-root`,30,`g`],[`garlic`,5,`clove`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 32 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 32 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:32,i:[[`scotch-bonnet-pepper`,1,`pcs`],[`ground-coriander`,6,`g`],[`ground-nutmeg`,3,`g`],[`dried-thyme`,4,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`parsley`,20,`g`],[`table-salt`,null,`to_taste`]]}];var u={slug:n,id:t,country:`NG`,region:r,servings:4,minutes:66,title:g,text:l,steps:m};export{a as country,u as default,t as id,o as minutes,r as region,s as servings,n as slug,m as steps,l as text,g as title};